			// SameTerm applies to the filter's argument
			SameTerm sameTerm = (SameTerm) filter.getCondition();
			TupleExpr filterArg = filter.getArg();

			ValueExpr leftArg = sameTerm.getLeftArg();
			ValueExpr rightArg = sameTerm.getRightArg();
			QueryAlgebraBindingAnalysis.ReadOnlyContext context = bindingAnalysis.contextAt(filter.getCondition());
			QueryAlgebraBindingAnalysis.OutputFacts argumentFacts = bindingAnalysis.outputFacts(filterArg,
					bindingAnalysis.contextAt(filter));

